class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


def binary_tree_paths(root):
    if not root:
        return []
    paths = []

    def dfs(node, path):
        path += str(node.val)
        if not node.left and not node.right:
            paths.append(path)
            return
        if node.left:
            dfs(node.left, path + "->")
        if node.right:
            dfs(node.right, path + "->")

    dfs(root, "")
    return paths
